import{_ as t,o as a,c as n,a4 as i}from"./chunks/framework.BMj-uaUw.js";const g=JSON.parse('{"title":"单元 11 · AI 协作：走一遍从规格到实现的完整流程","description":"","frontmatter":{},"headers":[{"level":2,"title":"这一章哪些活能交给 AI","slug":"这一章哪些活能交给-ai","link":"#这一章哪些活能交给-ai","children":[]},{"level":2,"title":"提示词怎么写","slug":"提示词怎么写","link":"#提示词怎么写","children":[{"level":3,"title":"1. 先搞清规格驱动开发在做什么","slug":"_1-先搞清规格驱动开发在做什么","link":"#_1-先搞清规格驱动开发在做什么","children":[]},{"level":3,"title":"2. 让它先复述需求确认理解","slug":"_2-让它先复述需求确认理解","link":"#_2-让它先复述需求确认理解","children":[]},{"level":3,"title":"3. 给它一份规格再让它实现","slug":"_3-给它一份规格再让它实现","link":"#_3-给它一份规格再让它实现","children":[]},{"level":3,"title":"4. 让它按 AGENTS.md 逐条自查","slug":"_4-让它按-agents-md-逐条自查","link":"#_4-让它按-agents-md-逐条自查","children":[]}]},{"level":2,"title":"AI 在这一章容易错什么","slug":"ai-在这一章容易错什么","link":"#ai-在这一章容易错什么","children":[{"level":3,"title":"一次让它生成太多","slug":"一次让它生成太多","link":"#一次让它生成太多","children":[]},{"level":3,"title":"产出不符合项目已有的约定","slug":"产出不符合项目已有的约定","link":"#产出不符合项目已有的约定","children":[]},{"level":3,"title":"编造字段与接口","slug":"编造字段与接口","link":"#编造字段与接口","children":[]}]},{"level":2,"title":"怎么验收 AI 的产出","slug":"怎么验收-ai-的产出","link":"#怎么验收-ai-的产出","children":[]},{"level":2,"title":"练习","slug":"练习","link":"#练习","children":[{"level":3,"title":"用“规格 → 实现 → 验收”走一遍一个新页面","slug":"用-规格-→-实现-→-验收-走一遍一个新页面","link":"#用-规格-→-实现-→-验收-走一遍一个新页面","children":[]}]}],"relativePath":"unit11/ai-collaboration.md","filePath":"unit11/ai-collaboration.md","lastUpdated":1789356894000}'),e={name:"unit11/ai-collaboration.md"};function l(p,s,r,o,d,h){return a(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="单元-11-·-ai-协作-走一遍从规格到实现的完整流程" tabindex="-1">单元 11 · AI 协作：走一遍从规格到实现的完整流程 <a class="header-anchor" href="#单元-11-·-ai-协作-走一遍从规格到实现的完整流程" aria-label="Permalink to &quot;单元 11 · AI 协作：走一遍从规格到实现的完整流程&quot;">​</a></h1><p>前面十章的 AI 协作，都是“问它一个知识点”或者“让它改一段代码”。这一章不一样 —— 从这一周开始，你要<strong>让它按规格实现一个完整的页面</strong>。</p><p>这是 AI 编码真正的主战场，也是最容易失控的地方。失控的方式有两种：一种是它一次生成十几个文件，你没读完就提交了；另一种是它按自己的习惯搭了一套结构和你的项目对不上，等你发现的时候已经有三个页面依赖它了。</p><p>这一节要讲的就是怎么把这件事控制在可验收的范围内。方法只有一个：<strong>先把规格写清楚。</strong></p><h2 id="这一章哪些活能交给-ai" tabindex="-1">这一章哪些活能交给 AI <a class="header-anchor" href="#这一章哪些活能交给-ai" aria-label="Permalink to &quot;这一章哪些活能交给 AI&quot;">​</a></h2><p>判断标准：<strong>规格里写明的事可以交给它实现，规格里没写的部分一律不能让它补。</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>能交给 AI 吗</th><th>为什么</th></tr></thead><tbody><tr><td>把规格文档整理成给 AI 的任务说明</td><td>可以</td><td>整理和改写，机械工作</td></tr><tr><td>按规格实现一个页面</td><td>可以</td><td>但要严格限定“只创建哪几个文件”</td></tr><tr><td>按 AGENTS.md 逐条自查产出</td><td>可以</td><td>有清单的检查它做得快</td></tr><tr><td>解释某个接口字段的用途</td><td>可以</td><td>快速确认理解</td></tr><tr><td>起草页面的四态结构</td><td>可以</td><td>前面几个单元已经建立了这个习惯</td></tr><tr><td>起草任务清单的条目</td><td>可以</td><td>但优先级要你自己排</td></tr><tr><td>判断“这个需求该拆成几个页面”</td><td><strong>不能直接信</strong></td><td>它倾向一步到位，拆得不够细</td></tr><tr><td>补上规格里没写的接口或字段</td><td><strong>不能直接信</strong></td><td>它会按常见命名编一个出来</td></tr><tr><td>决定第一版做哪些功能、不做哪些</td><td><strong>不行</strong></td><td>取决于时间与课程要求</td></tr><tr><td>决定页面之间的跳转关系</td><td><strong>不行</strong></td><td>取决于业务流程</td></tr></tbody></table><p><strong>倒数第三行是这一章最需要提防的。</strong> 它编出来的字段名往往比真的还像真的 —— <code>activityStatus</code>、<code>signupCount</code>、<code>createTime</code> 这种命名挑不出毛病，但它和你们后端的字段可能根本不是一个。</p><h2 id="提示词怎么写" tabindex="-1">提示词怎么写 <a class="header-anchor" href="#提示词怎么写" aria-label="Permalink to &quot;提示词怎么写&quot;">​</a></h2><h3 id="_1-先搞清规格驱动开发在做什么" tabindex="-1">1. 先搞清规格驱动开发在做什么 <a class="header-anchor" href="#_1-先搞清规格驱动开发在做什么" aria-label="Permalink to &quot;1. 先搞清规格驱动开发在做什么&quot;">​</a></h3><p>这一章的用法有个正式名字，叫<strong>规格驱动开发（Spec-Driven Development）</strong>。四个要点：</p><p><strong>一、核心主张：先写规格，再让 AI 实现。</strong> 代码是规格的落地，规格本身是可以被审阅、被讨论、被修改的产物。</p><p><strong>二、为什么需要它。</strong> 因为“一次让 AI 写太多”出来的东西对不上需求，而返工的成本比一开始写清楚更高。更麻烦的是：<strong>返工时你不知道该改哪里，因为整段代码都是它生成的，你只是“觉得不对”。</strong></p><p><strong>三、流程长什么样。</strong> GitHub 的 Spec Kit 把这套流程做成了工具链（2025 年 9 月发布，2026 年中已超过 13 万 star，支持 38 种 AI 编码工具），它的命令顺序是：</p><table tabindex="0"><thead><tr><th>顺序</th><th>做什么</th></tr></thead><tbody><tr><td>1</td><td>立项目原则（相当于 AGENTS.md）</td></tr><tr><td>2</td><td>写规格 —— 只写做什么、为什么，<strong>不写技术栈</strong></td></tr><tr><td>3</td><td>澄清模糊点</td></tr><tr><td>4</td><td>生成质量清单</td></tr><tr><td>5</td><td>写技术计划</td></tr><tr><td>6</td><td>拆任务清单</td></tr><tr><td>7</td><td>跨产物一致性检查</td></tr><tr><td>8</td><td>执行实现</td></tr></tbody></table><p>国内的编码工具也在往同一个方向走 —— 腾讯 CodeBuddy 主打的规范驱动开发就是同一套思路：需求澄清、任务拆解、代码预审、安全拦截。<strong>你不必用这些工具，用手写 Markdown 走同样的流程，效果一样。</strong></p><p><strong>四、为什么这一章要再讲一次 AGENTS.md。</strong> <a href="/frontend-engineering-course/unit03/ai-collaboration.html">单元 3</a>讲的是“AGENTS.md 是什么、写什么”；这一章讲的是“<strong>怎么用它</strong>”—— 它是流程里的第 1 步（项目原则），后面所有步骤都建立在它之上。规格里可以不写技术栈，但技术栈必须已经写在 AGENTS.md 里 —— 否则 AI 会自己选一套。</p><p><strong>本项目的规格不用另写。</strong> 你在<a href="/frontend-engineering-course/project/">项目规格</a>里看到的这几份文档本身就构成规格：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 需求规格说明          做什么、为什么做、有哪些字段</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>② 业务规则与状态流转     名额怎么算、冲突怎么判、状态怎么变</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>③ 接口约定              路径、参数、返回结构、错误码</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>④ 目录结构与命名约定     文件放哪、怎么命名</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>⑤ 页面清单与任务清单     拆成一次能做完的小任务</span></span></code></pre></div><p>前四份是给定的，<strong>第五份要你自己拆。</strong> 这一节练的其实就是第五份怎么写。</p><h3 id="_2-让它先复述需求确认理解" tabindex="-1">2. 让它先复述需求确认理解 <a class="header-anchor" href="#_2-让它先复述需求确认理解" aria-label="Permalink to &quot;2. 让它先复述需求确认理解&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先读根目录的 AGENTS.md，以及 docs/页面清单.md 里“页面 4 · 活动列表”一节。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要写代码。先告诉我三件事：</span></span>
<span class="line"><span>1. 用你自己的话复述一遍这个页面要做什么，包括有哪几块内容</span></span>
<span class="line"><span>2. 这个页面有哪些状态需要处理（加载中、出错、空数据等）</span></span>
<span class="line"><span>3. 有哪几处你觉得描述不明确、需要我确认</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 3 项按“会影响实现方式”的程度排序。</span></span></code></pre></div><p><strong>为什么这么写</strong>：这一步看起来多花了五分钟，省下的往往是半小时。<strong>理解偏差在写代码之前暴露出来，改的是一句话；在写完之后暴露出来，改的是十几个文件。</strong></p><p>第 3 点最有价值 —— 它列出来的“不明确处”通常正是你没想清楚的地方。你在写规格的时候觉得已经说清了，它一问才发现“筛选条件变化后要不要回到第一页”这种事你根本没写。</p><h3 id="_3-给它一份规格再让它实现" tabindex="-1">3. 给它一份规格再让它实现 <a class="header-anchor" href="#_3-给它一份规格再让它实现" aria-label="Permalink to &quot;3. 给它一份规格再让它实现&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读 AGENTS.md 和 docs/任务/04-活动列表.md，按里面的要求实现这个页面。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>1. 只创建或修改这两个文件：src/views/activity-list.vue、src/api/activity.js</span></span>
<span class="line"><span>2. 接口只用 docs/接口清单.md 里已有的，不要新增接口</span></span>
<span class="line"><span>3. 字段名在 api 层转成驼峰，页面里不出现下划线字段</span></span>
<span class="line"><span>4. 用 script setup 的组合式写法，不用选项式 API</span></span>
<span class="line"><span>5. 页面要有四态：加载中、出错、空数据、有数据</span></span>
<span class="line"><span></span></span>
<span class="line"><span>完成后按这个格式汇报：</span></span>
<span class="line"><span>- 改了哪些文件，每个文件做了什么</span></span>
<span class="line"><span>- 哪些地方是我没写清楚、你自己决定的（逐条列出）</span></span>
<span class="line"><span>- 有哪些地方你不确定，需要我确认</span></span></code></pre></div><p><strong>为什么这么写</strong>：五条约束里，第 1 条和第 2 条最关键，它们把“它可能做的事”框死了。<strong>不限定文件范围，它会顺手改你的请求层、动你的 store、往 <code>utils</code> 里加东西</strong> —— 每一处都可能是新的问题源。</p><p>汇报格式里的第 2 项是这段提示词的核心：<strong>让它主动列出“你自己决定的部分”</strong>，那些就是你要逐条核实的清单。它自己决定的越少，你的核对成本越低 —— 所以如果这一项列了七八条，说明你的规格写得太粗，回去补。</p><h3 id="_4-让它按-agents-md-逐条自查" tabindex="-1">4. 让它按 AGENTS.md 逐条自查 <a class="header-anchor" href="#_4-让它按-agents-md-逐条自查" aria-label="Permalink to &quot;4. 让它按 AGENTS.md 逐条自查&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读根目录的 AGENTS.md，把它里的每一条约定都当成一条检查项，</span></span>
<span class="line"><span>逐条检查你刚才生成的代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出用表格：约定的原文 / 我的代码符不符合 / 在哪一行 / 不符合的话怎么改。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 每一条都要出现，符合的也写出来</span></span>
<span class="line"><span>2. 不要改代码，只给表</span></span>
<span class="line"><span>3. 如果有某条约定你判断不了，直接写“判断不了”并说明缺什么信息</span></span></code></pre></div><p><strong>为什么这么写</strong>：这一步是把 AGENTS.md 从“写给 AI 看的文件”变成“AI 用的检查清单”。<strong>同一份文件，读一遍和当检查项用一遍，效果差很多</strong> —— 前者它只当背景知识，后者它必须逐条给出结论。</p><p>要求“符合的也写出来”和“判断不了的写判断不了”，都是为了堵住偷工减料。少了这两句，它容易只报两三条问题、剩下的一笔带过，让你误以为其余都没问题。</p><h2 id="ai-在这一章容易错什么" tabindex="-1">AI 在这一章容易错什么 <a class="header-anchor" href="#ai-在这一章容易错什么" aria-label="Permalink to &quot;AI 在这一章容易错什么&quot;">​</a></h2><h3 id="一次让它生成太多" tabindex="-1">一次让它生成太多 <a class="header-anchor" href="#一次让它生成太多" aria-label="Permalink to &quot;一次让它生成太多&quot;">​</a></h3><p><strong>现象</strong>：你写“帮我做活动管理模块”，它一次给出五个页面的代码，外加 store、api、路由、以及几个你没想到的组件。文件加起来两千多行。</p><p><strong>原因</strong>：从它的角度，“一次做完”是最省事的方案 —— 不用等你反馈，也不用在多轮之间保持一致。它没有“我要花半天才能读完这些代码”这个视角。</p><p><strong>怎么处理</strong>：<strong>一次只做一个页面，而且只做能在一小时内读完的量。</strong> 判断标准很简单：</p><blockquote><p>它给你的代码，你有没有把握<strong>逐行读完并解释</strong>？没有，就说明给多了。</p></blockquote><p>把任务切小的具体做法，就是在规格的“完成标准”里写清边界。比如：</p><table tabindex="0"><thead><tr><th>切法</th><th>一次的范围</th></tr></thead><tbody><tr><td>按页面切</td><td>一次一个页面，先列表页再表单页</td></tr><tr><td>按功能切</td><td>先“能显示数据”，再“能筛选”，最后“能分页”</td></tr><tr><td>按文件切</td><td>先 api 层，再页面组件，最后路由与菜单</td></tr></tbody></table><p><strong>“不做”这一节比“要做”更能约束范围。</strong> 写清“不做批量操作、不做导出、不做列自定义”，它就不会顺手给你加上。</p><h3 id="产出不符合项目已有的约定" tabindex="-1">产出不符合项目已有的约定 <a class="header-anchor" href="#产出不符合项目已有的约定" aria-label="Permalink to &quot;产出不符合项目已有的约定&quot;">​</a></h3><p><strong>现象</strong>：它新建了一个 <code>src/services/activityService.js</code>，或者自己写了一个 <code>request.js</code>，或者组件里直接 <code>axios.get</code>，或者用了 <code>element-plus</code> 的另一种写法。每一样单独看都合理，合起来看是另一套项目。</p><p><strong>原因</strong>：它不知道你的项目里已经有什么。你不给它看现有代码，它就只能按“一个典型项目应该长什么样”来搭 —— 而“典型项目”和“你们的项目”不是一回事。</p><p><strong>怎么处理</strong>：三件事一起做。</p><ol><li><strong>提示词里限定文件范围</strong>（第 3 个模板的第 1 条）。范围限定死了，它想另起一套也没有地方放。</li><li><strong>让它先读 AGENTS.md 和已有的同类文件。</strong> 提示词第一句就写“读 AGENTS.md”，再补一句“参考 <code>src/views/session-list.vue</code> 的写法”，效果更好 —— 有现成的例子照着，它不会自己发明。</li><li><strong>在 AGENTS.md 的禁止事项里写明。</strong> 本项目的那五条里，“不要引入新的 UI 库或状态管理库”和“不要修改 <code>src/utils/request.js</code> 里的拦截器逻辑”正是防这个的。</li></ol><p><strong>判断有没有另起一套，最快的办法是看文件清单。</strong> 它汇报“新建了这几个文件”时，你逐个对一下 <code>src/</code> 的目录约定 —— 出现约定之外的目录，就是跑偏了。</p><h3 id="编造字段与接口" tabindex="-1">编造字段与接口 <a class="header-anchor" href="#编造字段与接口" aria-label="Permalink to &quot;编造字段与接口&quot;">​</a></h3><p><strong>现象</strong>：它写出来的代码里有 <code>res.data.signupCount</code>、<code>activity.status === &#39;PUBLISHED&#39;</code>、<code>api.getActivityDetail(id, { withStats: true })</code>。这些字段、状态值、参数，你的接口清单里都没有。</p><p><strong>原因</strong>：这是幻觉依赖在业务层的版本。它按“一个活动管理系统应该有这些字段”来补，因为这些命名在它见过的项目里高频出现。<strong>它补得越合理，你越容易放过。</strong></p><p><strong>怎么处理</strong>：<strong>接口和字段只能从接口清单里来，不能用它给的。</strong> 两个具体的检查动作：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 把代码里用到的字段名抽出来，和后端返回的对照</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;res\\.[a-zA-Z]*\\.[a-zA-Z]*&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/views/activity-list.vue</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 把代码里用到的状态值抽出来，和状态流转文档对照</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&#39;[A-Z_]\\{3,\\}&#39;&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/views/activity-list.vue</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span></span></code></pre></div><p>本项目的活动状态只有四个：<code>DRAFT</code>、<code>SIGNING</code>、<code>SIGNUP_CLOSED</code>、<code>FINISHED</code>。<strong>如果它写出了 <code>PUBLISHED</code>、<code>ONGOING</code>、<code>CLOSED</code> 这类值，说明它是编的</strong> —— 而且这个错很隐蔽，因为状态判断错了往往只是“某个筛选条件不生效”，页面上看不出异常。</p><p>顺带说一个本项目里特别容易编错的地方：<strong>下架是独立的布尔标记 <code>offShelf</code>，不是一种状态。</strong> 如果它把下架写成了 <code>status === &#39;OFF_SHELF&#39;</code>，那整套状态判断都错了。</p><details class="details custom-block"><summary>还有一类错误：硬编码假数据，交付时忘了换</summary><p><strong>现象</strong>：页面里写着 <code>const list = ref([{ id: 1, title: &#39;测试活动&#39;, status: &#39;SIGNING&#39; }])</code>，或者 <code>// TODO: 接接口</code> 然后一直没接。</p><p><strong>原因</strong>：这是它“让页面先跑起来”的常用手段 —— 有假数据，界面立刻能看，你能马上判断布局对不对。本身不算错，<strong>错在忘了换。</strong></p><p><strong>怎么处理</strong>：<strong>允许它用假数据，但要求它把假数据集中在一处并标记出来。</strong></p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✓ 集中在文件顶部，一眼能看到</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// TODO(临时数据): 接口联调后删除，见 docs/任务/04-活动列表.md</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MOCK_LIST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* ... */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MOCK_LIST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>这样做有两个好处：一是交付前搜 <code>MOCK_</code> 或 <code>TODO(临时数据)</code> 就能全找出来，二是它不会散落在十几个地方。</p><p><strong>交付前一定搜一遍这三类东西：</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 假数据</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MOCK_\\|mockData\\|测试活动\\|张三\\|TODO&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 调试输出</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console\\.log&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 硬编码的地址</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;localhost\\|127\\.0\\.0\\.1\\|http://&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span></span></code></pre></div><p>这三条命令<a href="/frontend-engineering-course/unit12/ai-collaboration.html">单元 12</a>讲部署前检查时还会用到。<strong>把它们写进提交前的自查习惯里，比每次靠记可靠。</strong></p></details><h2 id="怎么验收-ai-的产出" tabindex="-1">怎么验收 AI 的产出 <a class="header-anchor" href="#怎么验收-ai-的产出" aria-label="Permalink to &quot;怎么验收 AI 的产出&quot;">​</a></h2><p>这一章的验收动作要照着规格逐条过，而且必须<strong>在浏览器里真的走一遍</strong>。</p><ul><li>[ ] 规格里的每一条“完成标准”，你都动手验证过了（不是读代码判断的）</li><li>[ ] 规格里的“不做”，它确实没做</li><li>[ ] 它只改了提示词里限定的文件，没有动 request.js、没有加新依赖</li><li>[ ] 代码里用到的字段名，全部在接口清单里能找到</li><li>[ ] 代码里用到的状态值，全部在状态流转文档里能找到（四个状态，下架是独立标记）</li><li>[ ] 它汇报的“自己决定的部分”，你逐条确认过，该改规格的回去改规格</li><li>[ ] 按 AGENTS.md 自查的表里，没有“判断不了”的行留着</li><li>[ ] 没有 <code>MOCK_</code>、<code>console.log</code>、硬编码地址残留</li></ul><p>前两条对应“做完了没、做多了没”，中间三条对应“有没有编东西”，后三条对应“该收的尾收了没”。<strong>这八条过完，这个页面才算是“按规格交付”，不是“碰巧能跑”。</strong></p><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><h3 id="用-规格-→-实现-→-验收-走一遍一个新页面" tabindex="-1">用“规格 → 实现 → 验收”走一遍一个新页面 <a class="header-anchor" href="#用-规格-→-实现-→-验收-走一遍一个新页面" aria-label="Permalink to &quot;用“规格 → 实现 → 验收”走一遍一个新页面&quot;">​</a></h3><p><strong>任务</strong>：从项目的页面清单里挑一个还没做的页面，完整走一遍四个步骤：写规格 → 让 AI 实现 → 验收 → 记录。<strong>记录里要写清它返工了几次、每次是因为什么。</strong></p><p><strong>要求</strong>：记录里必须包含这四项：</p><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>你的规格文档</td><td>四节齐全：目标、约束、不做、完成标准</td></tr><tr><td>给 AI 的提示词</td><td>完整保留，包括你限定文件范围的那一段</td></tr><tr><td>验收结果</td><td>逐条对照完成标准，写清哪几条过了、哪条没过</td></tr><tr><td>返工记录</td><td>每次返工写清“因为什么、改了规格还是改了提示词”</td></tr></tbody></table><details class="details custom-block"><summary>验收标准与参考思路</summary><p><strong>为什么重点记“返工因为什么”</strong>：因为返工的原因就是你规格里的漏洞。<strong>同一类漏洞改一次规格就够了，下次不用再返工。</strong> 这才是这一节真正要你带走的东西 —— 不是“学会用 AI 写页面”，而是“学会写一份不用返工的规格”。</p><p><strong>思路提示</strong>：</p><ul><li>第一次写规格别追求完美，写完就让它实现一遍。<strong>先跑一轮，你才知道自己的规格漏了什么。</strong> 空想是想不到的。</li><li>验收时严格执行“动手验证”这一条。规格里写“删除最后一页最后一条后，停留在上一页而不是空白页”，那就真的删一次看看 —— 读代码判断出来的“应该没问题”，不算过。</li><li>返工记录里区分两类：<strong>规格没写清</strong>（回去补规格）、<strong>它没按规格做</strong>（改提示词，把那条约束写得更硬）。这两类的处理方式不同，混在一起就学不到东西。</li><li>如果它一次生成的文件超过你半小时能读完的量，<strong>不要往下走，回去把任务切小。</strong> 这一步忍住了，后面会省很多事。</li><li>做完把它当检查项用一遍（第 4 个提示词模板）。<strong>这一步花的时间最少，发现的问题往往最多。</strong></li></ul><p><strong>不合格的写法</strong>：</p><blockquote><p>让 AI 做了活动列表页，改了几次，现在能跑起来了。</p></blockquote><p>“能跑起来”是这一章最低的标准。规格里的“完成标准”写了几条？过了几条？返工了几次、为什么返工？</p><p><strong>合格的写法</strong>：</p><blockquote><p>规格我写了目标、约束、不做、完成标准四节，完成标准里列了三条。 第一次实现返工了两处： 一是它用了 <code>status === &#39;PUBLISHED&#39;</code>，接口清单里没有这个值，是我把状态流转文档贴给它之后改对的； 二是筛选条件变化后没有回到第 1 页 —— 这一条我在规格里没写，所以回去补了规格，重新生成了一次。 完成后我按三条完成标准逐条验证：筛选项清空能恢复全量（过）、 删除最后一页最后一条会跳到空白页（没过，改了两行修好）、 后端关掉时显示错误态而不是一直转圈（过）。 最后按 AGENTS.md 自查，发现它用了 <code>.filter</code> 在模板里做筛选 —— 违反了“派生数据用 computed”这条， 改成计算属性了。 两条经验：<strong>状态值和分页行为这类东西，规格里不写明它就会自己编；规格里没写的事，一定会返工。</strong></p></blockquote><p>差别在于：后者不但完成了任务，还把两处返工转成了两条可以复用的规格经验。<strong>下一次写规格，这两条就不会再漏。</strong></p></details><hr><p>上一节：<a href="/frontend-engineering-course/unit11/05-form-page.html">11.5 表单页标准做法</a> · 课后练习：<a href="/frontend-engineering-course/unit11/practice.html">单元 11 课后练习</a></p>`,67)])])}const k=t(e,[["render",l]]);export{g as __pageData,k as default};
